"""Column-wise exact multiplicity in Pascal's triangle."""

from __future__ import annotations

from math import comb
from typing import List, Tuple


def occurrences(t: int) -> List[Tuple[int, int]]:
    """Return every position (n, k) with C(n, k) = t, for t >= 2.

    A position with 2 <= k <= n-2 is determined by its column, because
    n -> C(n,k) is strictly increasing for fixed k >= 1.  Moreover an interior
    occurrence in column k forces C(2k, k) <= t, so only O(log t) columns can
    contribute.  We therefore binary-search each admissible column instead of
    scanning the O(sqrt(t)) candidate rows.
    """
    if t < 2:
        raise ValueError("multiplicity is finite only for t >= 2")
    positions: List[Tuple[int, int]] = [(t, 1)]
    if t > 2:
        positions.append((t, t - 1))
    k = 2
    while comb(2 * k, k) <= t:
        lo, hi = 2 * k, 2 * k
        while comb(hi, k) < t:
            hi *= 2
        while lo <= hi:
            mid = (lo + hi) // 2
            c = comb(mid, k)
            if c == t:
                positions.append((mid, k))
                if 2 * k != mid:
                    positions.append((mid, mid - k))
                break
            if c < t:
                lo = mid + 1
            else:
                hi = mid - 1
        k += 1
    return sorted(positions)


def multiplicity(t: int) -> int:
    """N(t), the number of positions of t in Pascal's triangle."""
    return len(occurrences(t))


if __name__ == "__main__":
    for t in (2, 6, 10, 120, 210, 3003):
        print(t, multiplicity(t), occurrences(t))

"""Vieta descent solving the norm form x^2 - x y - y^2 = +-5."""

from __future__ import annotations

from typing import List, Tuple


def norm_form(x: int, y: int) -> int:
    return x * x - x * y - y * y


def descent_certificate(x: int, y: int) -> List[Tuple[int, int, int]]:
    """Slide a solution of x^2 - xy - y^2 = +-5 down to the bottom (1, 2).

    The step (x, y) -> (y, x - y) preserves the solution set, negates the value
    of the form, and strictly decreases the first coordinate whenever x > y.
    The trace returned, read backwards, exhibits (x, y) as a pair of consecutive
    Lucas numbers (L_{i+1}, L_i); the number of steps is O(log x) because the
    pair shrinks by the golden ratio each time.
    """
    if norm_form(x, y) not in (5, -5):
        raise ValueError(f"({x}, {y}) is not a solution: form = {norm_form(x, y)}")
    trace: List[Tuple[int, int, int]] = []
    while True:
        trace.append((x, y, norm_form(x, y)))
        if (x, y) == (1, 2):
            return trace
        if x <= y:
            raise RuntimeError("unexpected bottom; input was not a natural solution")
        x, y = y, x - y


def lucas_index(x: int, y: int) -> int:
    """The index i with (x, y) = (L_{i+1}, L_i)."""
    return len(descent_certificate(x, y)) - 1


if __name__ == "__main__":
    for step in descent_certificate(521, 322):
        print(step)
    print("index:", lucas_index(521, 322))
